import { useMemory } from '@pixelkit-labs/sdk';

function MemoryHUD() {
  const { freeRAMMB, isLowMemory, purgeCaches } = useMemory();
  return (
    <View>
      <Text>Free: {freeRAMMB} MB</Text>
      {isLowMemory && <Button title="Purge caches" onPress={purgeCaches} />}
    </View>
  );
}
